circular:
#law A theorem x: s32 => x == x;
#law B theorem x: s32 => x == x;
#proof A { use B(x); }
#proof B { use A(x); }

waived_cycle:
#law A theorem x: s32 => x == x;
#law B theorem x: s32 => x == x;
#proof A { use B(x); }
#proof B { use A(x); }
#law_waive A "invalid";
#law_waive B "invalid";

unproved_lemma:
#law A theorem x: s32 => x == x;
#law B theorem x: s32 => x == x;
#law_waive B "pending";
#proof A { use B(x); }

bad_rewrite:
#law A theorem x: s32 => x + 1 == x;
#law B theorem x: s32 => x + 1 == x;
#proof A { ring; }
#proof B { rewrite A(x); refl; }

duplicate:
#law A theorem x: s32 => x == x;
#proof A { refl; }
#proof A { refl; }

foreign:
Host :: #system_library "host";
Read :: () -> s32 #foreign Host;
#law Bad theorem x: s32 => Read() == x;
#proof Bad { unfold Read; ring; }

loop:
Loop :: (x: s32) -> s32 { value: s32 = x; while value > 0 { value -= 1 }; return value }
#law Bad theorem x: s32 => Loop(x) == 0;
#proof Bad { unfold Loop; ring; }

recursion:
Rec :: (x: s32) -> s32 { return Rec(x) }
#law Bad theorem x: s32 => Rec(x) == x;
#proof Bad { unfold Rec; ring; }

waive_invalid:
#law Bad theorem x: s32 => x + 1 == x;
#proof Bad { ring; }
#law_waive Bad "cannot authorize an invalid proof";
